  "پرونده‌ی شما در یک مرکز": {"en": "Your record at a centre", "ar": "ملفك في أحد المراكز", "ur": "ایک مرکز میں آپ کا ریکارڈ", "tr": "Bir merkezdeki kaydınız", "de": "Ihr Datensatz bei einer Einrichtung", "fr": "Votre dossier dans un centre", "es": "Su expediente en un centro", "pt": "O seu registo num centro", "ru": "Ваша карточка в центре", "zh": "您在某机构的档案", "ja": "施設にあるあなたの記録", "hi": "किसी केंद्र में आपका रिकॉर्ड", "bn": "একটি কেন্দ্রে আপনার রেকর্ড", "id": "Catatan Anda di sebuah pusat"},
  "«${1}» شما را به‌عنوان بیمار یا مشتری ثبت کرده است. برای وصل‌شدن پرونده به حساب نویان، آن را در «پیام به مراکز» تأیید کنید": {"en": "“${1}” has registered you as a patient or customer. To link that record to your Noyan account, confirm it under “Messages to centres”", "ar": "سجّلك «${1}» كمريض أو عميل. لربط الملف بحسابك في نويان، أكّده في «رسائل إلى المراكز»", "ur": "«${1}» نے آپ کو مریض یا گاہک کے طور پر درج کیا ہے۔ ریکارڈ کو اپنے نویان اکاؤنٹ سے جوڑنے کے لیے «مراکز کو پیغام» میں اس کی تصدیق کریں", "tr": "“${1}” sizi hasta veya müşteri olarak kaydetti. Kaydı Noyan hesabınıza bağlamak için “Merkezlere mesajlar” bölümünden onaylayın", "de": "„${1}“ hat Sie als Patient oder Kunde erfasst. Um den Datensatz mit Ihrem Noyan-Konto zu verknüpfen, bestätigen Sie ihn unter „Nachrichten an Einrichtungen“", "fr": "« ${1} » vous a enregistré comme patient ou client. Pour relier ce dossier à votre compte Noyan, confirmez-le dans « Messages aux centres »", "es": "«${1}» le ha registrado como paciente o cliente. Para vincular ese expediente a su cuenta de Noyan, confírmelo en «Mensajes a centros»", "pt": "«${1}» registou-o como paciente ou cliente. Para ligar esse registo à sua conta Noyan, confirme-o em «Mensagens aos centros»", "ru": "«${1}» зарегистрировал вас как пациента или клиента. Чтобы привязать карточку к аккаунту Noyan, подтвердите это в разделе «Сообщения центрам»", "zh": "“${1}”已将您登记为患者或客户。如需将该档案关联到您的 Noyan 账户，请在“给机构的消息”中确认", "ja": "「${1}」があなたを患者または顧客として登録しました。この記録を Noyan アカウントに連携するには「施設へのメッセージ」で確認してください", "hi": "“${1}” ने आपको मरीज़ या ग्राहक के रूप में दर्ज किया है। रिकॉर्ड को अपने Noyan खाते से जोड़ने के लिए “केंद्रों को संदेश” में इसकी पुष्टि करें", "bn": "“${1}” আপনাকে রোগী বা গ্রাহক হিসেবে নথিভুক্ত করেছে। রেকর্ডটি আপনার Noyan অ্যাকাউন্টে যুক্ত করতে “কেন্দ্রে বার্তা” অংশে তা নিশ্চিত করুন", "id": "“${1}” telah mendaftarkan Anda sebagai pasien atau pelanggan. Untuk menautkan catatan itu ke akun Noyan Anda, konfirmasikan di “Pesan ke pusat”"},
  "شماره‌ی یک بیمار احتمالاً اشتباه است": {"en": "A patient's number may be wrong", "ar": "قد يكون رقم أحد المرضى خاطئًا", "ur": "ایک مریض کا نمبر شاید غلط ہے", "tr": "Bir hastanın numarası yanlış olabilir", "de": "Die Nummer eines Patienten ist möglicherweise falsch", "fr": "Le numéro d’un patient est peut-être erroné", "es": "El número de un paciente puede ser incorrecto", "pt": "O número de um paciente pode estar errado", "ru": "Номер пациента, возможно, указан неверно", "zh": "某位患者的号码可能有误", "ja": "患者の電話番号が誤っている可能性があります", "hi": "किसी मरीज़ का नंबर शायद गलत है", "bn": "একজন রোগীর নম্বর সম্ভবত ভুল", "id": "Nomor seorang pasien mungkin salah"},
  "دارنده‌ی شماره‌ی پرونده‌ی «${1}» در نویان گفته است که بیمار شما نیست؛ شماره را بررسی کنید": {"en": "The holder of the number on the record “${1}” said on Noyan that they are not your patient; please check the number", "ar": "قال صاحب الرقم المسجّل في ملف «${1}» على نويان إنه ليس مريضك؛ تحقّق من الرقم", "ur": "«${1}» کے ریکارڈ والے نمبر کے مالک نے نویان پر کہا ہے کہ وہ آپ کا مریض نہیں؛ نمبر کی جانچ کریں", "tr": "“${1}” kaydındaki numaranın sahibi Noyan’da hastanız olmadığını söyledi; numarayı kontrol edin", "de": "Der Inhaber der Nummer im Datensatz „${1}“ hat auf Noyan angegeben, nicht Ihr Patient zu sein; bitte prüfen Sie die Nummer", "fr": "Le titulaire du numéro du dossier « ${1} » a indiqué sur Noyan ne pas être votre patient ; vérifiez le numéro", "es": "El titular del número del expediente «${1}» ha indicado en Noyan que no es su paciente; compruebe el número", "pt": "O titular do número do registo «${1}» indicou na Noyan que não é seu paciente; verifique o número", "ru": "Владелец номера из карточки «${1}» сообщил в Noyan, что не является вашим пациентом; проверьте номер", "zh": "档案“${1}”上号码的持有人在 Noyan 表示自己不是您的患者，请核对号码", "ja": "記録「${1}」の電話番号の持ち主が Noyan で「あなたの患者ではない」と回答しました。番号を確認してください", "hi": "रिकॉर्ड “${1}” के नंबर के धारक ने Noyan पर कहा है कि वे आपके मरीज़ नहीं हैं; नंबर जाँचें", "bn": "“${1}” রেকর্ডের নম্বরের মালিক Noyan-এ জানিয়েছেন তিনি আপনার রোগী নন; নম্বরটি যাচাই করুন", "id": "Pemilik nomor pada catatan “${1}” menyatakan di Noyan bahwa ia bukan pasien Anda; periksa nomornya"},
