    "ar": "تم تفعيل لوحة الصيدلية لك. أكمل ملفك التعريفي ومنتجاتك من لوحة الصيدلية.",
    "ur": "آپ کے لیے فارمیسی پینل فعال کر دیا گیا۔ فارمیسی پینل سے اپنی پروفائل اور مصنوعات مکمل کریں۔",
    "tr": "Eczane paneliniz etkinleştirildi. Profilinizi ve ürünlerinizi eczane panelinden tamamlayın.",
    "de": "Ihr Apotheken-Panel ist jetzt aktiv. Vervollständigen Sie Ihr Profil und Ihre Produkte im Apotheken-Panel.",
