    "ar": "تم تفعيل لوحة العيادة لك. أكمل الملف التعريفي للعيادة وأطباءها وخدماتها من اللوحة.",
    "ur": "آپ کے لیے کلینک پینل فعال کر دیا گیا۔ پینل سے کلینک کی پروفائل، ڈاکٹرز اور خدمات مکمل کریں۔",
