    "ar": "أُضيفت شركة التأمين هذه إلى قائمة شركات التأمين التي تقبلها. ستصبح صفحتها عامة بعد مراجعة المدير.",
    "ur": "یہ بیمہ آپ کے قبول کردہ بیموں کی فہرست میں شامل کر دیا گیا۔ منتظم کے جائزے کے بعد اس کا صفحہ عوامی ہو جائے گا۔",
    "tr": "Bu sigorta, kabul ettiğiniz sigortalar listesine eklendi. Sayfası yönetici incelemesinden sonra herkese açık olacak.",
    "de": "Diese Versicherung wurde zu den von Ihnen akzeptierten Versicherungen hinzugefügt. Ihre Seite wird nach Prüfung durch einen Admin veröffentlicht.",
    "fr": "Cet assureur a été ajouté aux assurances que vous acceptez. Sa page sera publiée après validation par un administrateur.",
    "es": "Esta aseguradora se ha añadido a los seguros que acepta. Su página se publicará tras la revisión del administrador.",
    "pt": "Esta seguradora foi adicionada aos seguros que você aceita. A página será publicada após a revisão do administrador.",
    "ru": "Эта страховая добавлена в список принимаемых вами страховок. Её страница станет публичной после проверки администратором.",
    "zh": "该保险已加入您接受的保险列表。经管理员审核后，其页面将公开。",
    "ja": "この保険があなたの受け入れ保険の一覧に追加されました。管理者の確認後、ページが公開されます。",
    "hi": "यह बीमा आपके स्वीकार किए गए बीमों की सूची में जोड़ दिया गया है। व्यवस्थापक की समीक्षा के बाद इसका पेज सार्वजनिक होगा।",
    "bn": "এই বিমাটি আপনার গ্রহণ করা বিমার তালিকায় যুক্ত হয়েছে। অ্যাডমিনের পর্যালোচনার পর এর পেজ সবার জন্য প্রকাশিত হবে।",
    "id": "Asuransi ini telah ditambahkan ke daftar asuransi yang Anda terima. Halamannya akan dipublikasikan setelah ditinjau admin."
