    "en": "The doctor was ready at the appointment time and has been paid the fee. To cancel for free, do so at least 24 hours before the appointment.",
    "ar": "كان الطبيب جاهزًا في وقت الموعد وتم دفع رسوم الموعد له. للإلغاء المجاني، ألغِ الموعد قبل 24 ساعة على الأقل.",
    "ur": "ڈاکٹر اپائنٹمنٹ کے وقت تیار تھے اور انہیں فیس ادا کر دی گئی۔ مفت منسوخی کے لیے اپائنٹمنٹ سے کم از کم 24 گھنٹے پہلے منسوخ کریں۔",
    "tr": "Doktor randevu saatinde hazırdı ve randevu ücreti kendisine ödendi. Ücretsiz iptal için randevudan en az 24 saat önce iptal edin.",
