    "ru": "Врач был готов в назначенное время, и оплата за приём перечислена ему. Чтобы отменить бесплатно, сделайте это не позднее чем за 24 часа до приёма.",
    "zh": "医生在预约时间已就绪，预约费用已支付给医生。如需免费取消，请至少在预约前 24 小时操作。",
    "ja": "医師は予約時間に待機しており、予約料金は医師に支払われました。無料でキャンセルするには、予約の24時間前までに手続きしてください。",
    "hi": "डॉक्टर अपॉइंटमेंट के समय तैयार थे और उन्हें शुल्क का भुगतान कर दिया गया। मुफ़्त रद्दीकरण के लिए अपॉइंटमेंट से कम से कम 24 घंटे पहले रद्द करें।",
    "bn": "ডাক্তার অ্যাপয়েন্টমেন্টের সময় প্রস্তুত ছিলেন এবং ফি তাঁকে পরিশোধ করা হয়েছে। বিনামূল্যে বাতিল করতে অ্যাপয়েন্টমেন্টের অন্তত 24 ঘণ্টা আগে বাতিল করুন।",
    "id": "Dokter telah siap pada waktu janji temu dan biayanya telah dibayarkan kepada dokter. Untuk pembatalan gratis, batalkan paling lambat 24 jam sebelum janji temu."
